/**
 * This deployment's client build version (React Router's manifest hash),
 * written by scripts/build/finalize.ts. The SSR Function's HTML cache keys
 * carry it, so a deploy never serves HTML that references the previous
 * build's chunks, and a cache hit needs no server build loaded.
 */
// @ts-ignore -- generated by the build (absent before `npm run build`)
import info from "../../build/ssr/version.json"

export const SSR_BUILD_VERSION: string =
  (info as { version?: string } | undefined)?.version ?? "dev"
